const state={locale:localStorage.getItem("hex-locale")||"vi",bootstrap:null,game:null,snapshot:null,selectedDay:null,selectedAgent:0,plannerMode:"manual",method:"alns",params:{},timeLimit:"",session:null,sessionTimer:null,planText:"",roles:[],proposalFingerprint:null,zoom:1,replay:null,replayTimer:null,peerStandings:null,local:{catalog:null,groupId:"",caseId:"",caseData:null,method:"alns",result:null,running:false,dayIndex:0,step:0,playing:false,timer:null}};
const T=k=>I18N[state.locale]?.[k]??I18N.en[k]??k;

async function api(path,options){const response=await fetch(path,options);let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||`HTTP ${response.status}`);return data}
function toast(message,kind=""){const node=document.createElement("div");node.className=`toast ${kind}`;node.textContent=message;$("#toast-stack").append(node);setTimeout(()=>node.remove(),4200)}
function setConnection(ok,text="API"){const node=$("#connection");node.className=`connection ${ok?"ok":"error"}`;node.querySelector("span").textContent=text}
function post(path,body){return api(path,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)})}
function statusLabel(value){return T(value)||String(value||"").replaceAll("_"," ")}
function zoomIcon(kind){const path=kind==="in"?'<path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14"/><path d="M12 10h-2v2H9v-2H7V9h2V7h1v2h2z"/>':'<path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14M7 9h5v1H7z"/>';return`<svg viewBox="0 0 24 24" aria-hidden="true">${path}</svg>`}
function currentGameId(){const match=location.pathname.match(/^\/competition\/game\/(.+)$/);return match?decodeURIComponent(match[1]):null}
function isLocalRoute(){return location.pathname==="/local"}
function updateNav(){$("#competition-nav")?.classList.toggle("active",!isLocalRoute());$("#local-nav")?.classList.toggle("active",isLocalRoute())}
function ownTeamId(){return String(state.snapshot?.game_id||"").split(":").at(-1)}

async function boot(){
 try{state.bootstrap=await api("/api/bootstrap");setConnection(true);state.method=state.bootstrap.policies.includes("alns")?"alns":state.bootstrap.policies[0];state.local.method=state.method;renderLocale();updateNav();const gameId=currentGameId();if(gameId)await loadGame(gameId);else if(isLocalRoute())await loadLocal();else renderHome()}catch(error){setConnection(false,T("apiError"));$("#app").innerHTML=`<div class="empty"><h2>${esc(T("apiError"))}</h2><p>${esc(error.message)}</p></div>`}}
function renderLocale(){$("#locale-button").innerHTML=state.locale==="vi"?"🇻🇳 <span>vi</span>":"🇬🇧 <span>en</span>";document.documentElement.lang=state.locale}
function renderHome(){document.title=`${T("matches")} · HEXUDON`;const games=state.bootstrap.games||[];$("#app").innerHTML=`<div class="page-title-row"><h1>${esc(T("matches"))}</h1></div><section class="game-grid">${games.length?games.map(game=>`<article class="game-card"><div class="game-card-main"><span class="open-pill">${esc(T("open"))}</span><h2>${esc(game.name)}</h2><p><b>${game.width}×${game.height}</b> · ${game.total_days} ${esc(T("days").toLowerCase())}</p><p>${esc(game.question_id)}</p></div><div class="game-card-foot"><a class="primary-button wide row center-content" href="/competition/game/${encodeURIComponent(game.question_id)}">▶ ${esc(T("enter"))}</a></div></article>`).join(""):`<p>${esc(T("noGames"))}</p>`}</section>`}

async function loadLocal(){
 document.title=`${T("local")} · HEXUDON`;$("#team-badge").textContent="LOCAL";clearInterval(state.local.timer);state.local.playing=false;
 try{
  if(!state.local.catalog)state.local.catalog=await api("/api/local/cases");
  const groups=state.local.catalog.groups||[];
  if(!groups.length){$("#app").innerHTML=`<div class="empty"><h2>${esc(T("localTests"))}</h2><p>${esc(T("noLocalCases"))}</p></div>`;return}
  if(!groups.some(group=>group.id===state.local.groupId))state.local.groupId=(groups.find(group=>group.tier==="brutal")||groups[0]).id;
  const group=groups.find(row=>row.id===state.local.groupId);
  if(!group.cases.some(row=>row.id===state.local.caseId))state.local.caseId=group.cases[0].id;
  if(state.local.caseData?.id!==state.local.caseId)state.local.caseData=await api(`/api/local/case?case_id=${encodeURIComponent(state.local.caseId)}`);
  renderLocal();
 }catch(error){toast(error.message,"error");$("#app").innerHTML=`<div class="empty"><h2>${esc(T("localTests"))}</h2><p>${esc(error.message)}</p></div>`}
}
function localGroup(){return(state.local.catalog?.groups||[]).find(row=>row.id===state.local.groupId)}
function localCaseMeta(){return localGroup()?.cases.find(row=>row.id===state.local.caseId)||{}}
function localParameters(){const defs=state.bootstrap.hyperparameters?.[state.local.method]||[],values=state.params[state.local.method]||{};return defs.map(field=>`<div class="parameter"><label>${esc(field.label)}</label><input class="input" data-local-param="${esc(field.key)}" type="number" value="${esc(values[field.key]??field.recommended??"")}" ${field.min!==undefined?`min="${field.min}"`:""} ${field.max!==undefined?`max="${field.max}"`:""} step="${field.step??"any"}"></div>`).join("")||`<span class="safety-note">Automatic defaults</span>`}
function localScoreMarkup(){const run=state.local.result?.result;if(!run)return"";const score=run.score||{},max=run.optimum_score||{},pct=run.objective_percentages||{};const metrics=[[T("types"),"distinct_types"],[T("daily"),"cumulative_daily_types"],[T("servings"),"total_servings"]];return`<section class="local-score-grid">${metrics.map(([label,key])=>`<article class="score-card"><span>${esc(label)}</span><strong>${score[key]??0}<small> / ${max[key]??0}</small></strong><div class="score-track"><i style="width:${Math.max(0,Math.min(100,Number(pct[key])||0))}%"></i></div><b>${Number(pct[key]??0).toFixed(1)}%</b></article>`).join("")}<article class="score-card compact"><span>${esc(T("runtime"))}</span><strong>${Number(run.runtime_seconds||0).toFixed(3)}<small>s</small></strong><b>${run.valid_days??0}/${(state.local.caseData?.scenario?.config?.daySteps||[]).length} ${esc(T("validDays").toLowerCase())}</b></article></section>`}
function localFrameView(){const run=state.local.result?.result,days=run?.replay?.days||[],day=days[state.local.dayIndex];if(!day)return null;const team=day.teams?.[0]||{},frames=team.frames||[],max=Math.max(0,frames.length-1),step=Math.min(state.local.step,max),frame=frames[step]||frames[0]||{},color="#1976d2";state.local.step=step;return{day,team,frames,max,step,frame,replayTeams:[{teamId:"local",label:state.local.method,color,agents:(frame.agents||[]).map((agent,index)=>({cell:Number(agent.cell),kind:agent.type==="refuel"||Number(agent.type)===1?1:0,fuel:agent.fuel,trail:replayTrail(frames,index,step)}))}],dayInfo:{traffics:Object.entries(day.road_condition||{}).map(([pos,status])=>({pos:Number(pos),status:Number(status)}))}}}
function localFrameStatsMarkup(view){const frame=view.frame,collected=(frame.collected||[]).length;return`<span class="chip">${esc(T("types"))}: ${frame.types??0}</span><span class="chip">${esc(T("servings"))}: ${frame.servings??0}</span><span class="chip ${collected?"success":""}">${esc(T("collected"))}: ${collected?`+${collected}`:"—"}</span>${(frame.agents||[]).map((agent,index)=>`<span class="agent-fuel-chip">#${index} ${agent.type==="refuel"||Number(agent.type)===1?esc(T("refuel")):`${esc(T("patrol"))} ⛽${agent.fuel??"—"}`}</span>`).join("")}`}
function localPlaybackMarkup(){const view=localFrameView();if(!view)return"";const days=state.local.result.result.replay.days,frame=view.frame,team=view.team;return`<section class="panel local-playback"><div class="local-playback-head"><div><span class="eyebrow">${esc(state.local.method)}</span><h2>${esc(T("replayTitle"))}</h2></div><div class="day-tabs">${days.map((day,index)=>`<button data-local-day="${index}" class="${index===state.local.dayIndex?"active":""}">${esc(T("day"))} ${Number(day.day)+1}</button>`).join("")}</div></div><div class="replay-controls"><button id="local-first" class="icon-button" title="${esc(T("first"))}">|◀</button><button id="local-play" class="icon-button" title="${esc(T("play"))}">${state.local.playing?"Ⅱ":"▶"}</button><button id="local-last" class="icon-button" title="${esc(T("last"))}">▶|</button><input id="local-range" type="range" min="0" max="${view.max}" value="${view.step}"><b id="local-step-label">${esc(T("steps"))} ${view.step}/${view.max}</b></div><div id="local-frame-stats" class="local-frame-stats">${localFrameStatsMarkup(view)}</div><div class="map-toolbar"><button class="icon-button map-icon-button" data-local-zoom="out">${zoomIcon("out")}</button><button class="zoom-label text-button" data-local-zoom="reset">${Math.round(state.zoom*100)}%</button><button class="icon-button map-icon-button" data-local-zoom="in">${zoomIcon("in")}</button></div><div class="map-wrap"><div id="local-map-canvas" class="map-canvas">${renderMap({config:state.local.caseData.scenario.config,day:view.dayInfo,replayTeams:view.replayTeams,highlightCells:frame.collected||[]})}</div></div>${legendMarkup(true)}<details class="local-actions"><summary>${esc(T("actionPlan"))} · ${esc(T("day"))} ${Number(view.day.day)+1}</summary><pre class="raw-json">${esc(JSON.stringify(team.actions,null,2))}</pre></details></section>`}
function renderLocal(){const groups=state.local.catalog?.groups||[],group=localGroup(),cases=group?.cases||[],meta=localCaseMeta(),scenario=state.local.caseData?.scenario,config=scenario?.config||{},design=scenario?.design||meta.design||{};$("#app").innerHTML=`<section class="local-heading"><div><span class="eyebrow">OFFLINE WORKSPACE</span><h1>${esc(T("localTests"))}</h1><p>${esc(T("localHelp"))}</p></div><span class="chip primary">${state.local.catalog?.case_count||0} cases</span></section><section class="panel local-controls"><div class="local-control-grid"><div class="field"><label>${esc(T("testSuite"))}</label><select id="local-group">${groups.map(row=>`<option value="${esc(row.id)}" ${row.id===state.local.groupId?"selected":""}>${esc(row.tier.toUpperCase())} · ${row.cases.length}</option>`).join("")}</select></div><div class="field"><label>${esc(T("testCase"))}</label><select id="local-case">${cases.map(row=>`<option value="${esc(row.id)}" ${row.id===state.local.caseId?"selected":""}>${esc(row.name)} · seed ${esc(row.seed??"—")}</option>`).join("")}</select></div><div class="field"><label>${esc(T("method"))}</label><select id="local-method">${state.bootstrap.policies.map(method=>`<option value="${esc(method)}" ${method===state.local.method?"selected":""}>${esc(method)}</option>`).join("")}</select></div><button id="run-local" class="primary-button" ${state.local.running?"disabled":""}>${state.local.running?`<span class="mini-spinner"></span> ${esc(T("runningLocal"))}`:`▶ ${esc(T("runLocal"))}`}</button></div><details class="local-parameters"><summary>Hyperparameters</summary><div class="parameters">${localParameters()}</div></details></section><section class="local-case-summary"><article><span>${esc(T("testCase"))}</span><strong>${esc(state.local.caseId)}</strong></article><article><span>${esc(T("target"))}</span><strong>${esc(scenario?.target||meta.target||"—")}</strong></article><article><span>${esc(T("mapSize"))}</span><strong>${config.map?.width||"—"} × ${config.map?.height||"—"}</strong></article><article><span>${esc(T("days"))}</span><strong>${config.daySteps?.length||"—"}</strong></article><article><span>${esc(T("fuel"))}</span><strong>${config.fuelLimits??design.fuel??"—"}</strong></article><article><span>${esc(T("spots"))}</span><strong>${config.spots?.length||"—"}</strong></article></section>${state.local.running?`<section class="panel local-running"><div class="spinner"></div><h3>${esc(T("runningLocal"))}</h3><p>${esc(state.local.caseId)} · ${esc(state.local.method)}</p></section>`:""}${localScoreMarkup()}${localPlaybackMarkup()}${!state.local.result&&!state.local.running?`<section class="panel map-panel"><div class="map-wrap"><div class="map-canvas">${renderMap({config,day:{traffics:[]},replayTeams:[{teamId:"start",label:"start",color:"#1976d2",agents:(config.agents||[]).map(cell=>({cell,kind:0}))}]})}</div></div>${legendMarkup()}</section>`:""}`;bindLocal()}
function collectLocalParams(){const result={};$$('[data-local-param]').forEach(input=>{if(input.value!=="")result[input.dataset.localParam]=Number(input.value)});return result}
function stopLocalPlayback(){state.local.playing=false;clearInterval(state.local.timer)}
function updateLocalPlayback(){const view=localFrameView();if(!view||!$("#local-range"))return;$("#local-range").value=String(view.step);$("#local-step-label").textContent=`${T("steps")} ${view.step}/${view.max}`;$("#local-play").textContent=state.local.playing?"Ⅱ":"▶";$("#local-frame-stats").innerHTML=localFrameStatsMarkup(view);$("#local-map-canvas").innerHTML=renderMap({config:state.local.caseData.scenario.config,day:view.dayInfo,replayTeams:view.replayTeams,highlightCells:view.frame.collected||[]})}
function bindLocal(){
 $("#local-group")?.addEventListener("change",async event=>{stopLocalPlayback();state.local.groupId=event.target.value;state.local.caseId="";state.local.caseData=null;state.local.result=null;await loadLocal()});
 $("#local-case")?.addEventListener("change",async event=>{stopLocalPlayback();state.local.caseId=event.target.value;state.local.caseData=null;state.local.result=null;await loadLocal()});
 $("#local-method")?.addEventListener("change",event=>{state.local.method=event.target.value;state.local.result=null;renderLocal()});
 $("#run-local")?.addEventListener("click",runLocal);
 $$('[data-local-day]').forEach(button=>button.addEventListener("click",()=>{stopLocalPlayback();state.local.dayIndex=Number(button.dataset.localDay);state.local.step=0;renderLocal()}));
 $("#local-range")?.addEventListener("input",event=>{stopLocalPlayback();state.local.step=Number(event.target.value);updateLocalPlayback()});
 $("#local-first")?.addEventListener("click",()=>{stopLocalPlayback();state.local.step=0;updateLocalPlayback()});
 $("#local-last")?.addEventListener("click",()=>{stopLocalPlayback();state.local.step=localFrameView()?.max||0;updateLocalPlayback()});
 $("#local-play")?.addEventListener("click",()=>{const view=localFrameView();if(!view)return;if(state.local.step>=view.max)state.local.step=0;state.local.playing=!state.local.playing;clearInterval(state.local.timer);if(state.local.playing)state.local.timer=setInterval(()=>{const current=localFrameView();if(!current||state.local.step>=current.max)stopLocalPlayback();else state.local.step++;updateLocalPlayback()},350);updateLocalPlayback()});
 $$('[data-local-zoom]').forEach(button=>button.addEventListener("click",()=>{state.zoom=button.dataset.localZoom==="in"?Math.min(3,state.zoom*1.25):button.dataset.localZoom==="out"?Math.max(.5,state.zoom/1.25):1;renderLocal()}));
}
async function runLocal(){try{stopLocalPlayback();const params=collectLocalParams();state.params[state.local.method]=params;state.local.running=true;state.local.result=null;renderLocal();state.local.result=await post("/api/local/run",{case_id:state.local.caseId,method:state.local.method,hyperparameters:params});state.local.dayIndex=0;state.local.step=0;toast(`${state.local.method} · ${T("finished")}`,"success")}catch(error){toast(error.message,"error")}finally{state.local.running=false;renderLocal()}}

async function loadGame(gameId,{quiet=false}={}){
 try{if(!quiet)$("#app").innerHTML=`<section class="loading-screen"><div class="spinner"></div><p>${esc(T("loading"))}…</p></section>`;state.snapshot=await api(`/api/games/${encodeURIComponent(gameId)}/snapshot`);state.game=(state.bootstrap.games||[]).find(g=>g.question_id===gameId)||{question_id:gameId,name:"HEXUDON",is_practice:state.snapshot.board?.is_practice,no_reset:state.snapshot.board?.no_reset,total_days:state.snapshot.config?.daySteps?.length};state.peerStandings=state.game.is_practice?{loading:true}:null;const day=Number(state.snapshot.state?.day);if(state.selectedDay===null)state.selectedDay=Number.isFinite(day)?Math.min(day,(state.game.total_days||1)-1):0;document.title=`${state.game.name} · HEXUDON`;$("#team-badge").textContent=`ID:${ownTeamId()||"?"}`;await restoreSession();renderGame();if(state.game.is_practice)loadStandings()}catch(error){toast(error.message,"error");if(!quiet)$("#app").innerHTML=`<div class="empty"><h2>HEXUDON</h2><p>${esc(error.message)}</p><a href="/" class="secondary-button">${esc(T("back"))}</a></div>`}}
async function loadStandings(){const gameId=state.game?.question_id;if(!gameId)return;try{const data=await api(`/api/games/${encodeURIComponent(gameId)}/standings`);if(state.game?.question_id!==gameId)return;state.peerStandings=data}catch(error){if(state.game?.question_id!==gameId)return;state.peerStandings={error:error.message}}const current=$(".standings");if(current)current.outerHTML=standingsMarkup()}
async function restoreSession(){try{if(state.session&&!terminal.has(state.session.state)){state.session=await api(`/api/play/sessions/${state.session.id}`);state.plannerMode=state.session.execution_mode||"manual";syncProposal();scheduleSessionPoll();return}const data=await api("/api/play/sessions");const match=(data.sessions||[]).find(s=>s.requested_game_id===state.game.question_id&&!terminal.has(s.state));if(match){state.session=match;state.plannerMode=match.execution_mode||"manual";syncProposal();scheduleSessionPoll()}}catch{}}

function gameModeLabel(){if(state.game.is_practice&&state.game.no_reset)return T("competitivePractice");if(state.game.is_practice)return T("practice");return T("live")}
function scoreSummary(){const team=state.snapshot.state?.teams?.[ownTeamId()]||{};return{types:(team.distinct_types||[]).length,servings:team.total_servings??0,submits:team.submit_count??0}}
function plannerParameters(){const defs=state.bootstrap.hyperparameters?.[state.method]||[];const values=state.params[state.method]||{};return defs.map(field=>`<div class="parameter"><label>${esc(field.label)}</label><input class="input" data-param="${esc(field.key)}" type="number" value="${esc(values[field.key]??field.recommended??"")}" ${field.min!==undefined?`min="${field.min}"`:""} ${field.max!==undefined?`max="${field.max}"`:""} step="${field.step??"any"}"></div>`).join("")||`<span class="safety-note">Automatic defaults</span>`}
function roleEditor(proposal){const count=state.snapshot.config?.agents?.length||0;if(!state.roles.length)state.roles=proposal?.types?.slice()||new Array(count).fill(0);return`<div class="notice">ⓘ <span>${esc(T("agentHint"))}</span></div><div class="role-list">${state.roles.map((kind,index)=>`<div class="role-row"><span>${esc(T("day").replace("Ngày","Xe").replace("Day","Agent"))} ${index} — #${state.snapshot.config.agents[index]}</span><div class="toggle-group"><button data-role-index="${index}" data-role="0" class="${kind===0?"active":""}">${esc(T("patrol"))} (0)</button><button data-role-index="${index}" data-role="1" class="${kind===1?"active":""}">${esc(T("refuel"))} (1)</button></div></div>`).join("")}</div>`}
function planEditor(proposal){const dayInfo=state.session?.snapshot?.day||state.snapshot.day||{},agents=dayInfo.agents||[],steps=dayInfo.steps??state.snapshot.config?.daySteps?.[state.selectedDay]??"—";if(!state.planText){const count=agents.length||state.snapshot.config?.agents?.length||0;state.planText=JSON.stringify(proposal?.actions||Array.from({length:count},()=>[-Number(steps)]))}const agentSelector=agents.length?`<div class="agent-chips">${agents.map((agent,index)=>`<button data-agent-select="${index}" class="${index===state.selectedAgent?"active":""}">#${index} ${esc(Number(agent.kind)===0?T("patrol"):T("refuel"))} · ${proposal?.actions?.[index]?steps:0}/${steps}</button>`).join("")}</div>`:"";return`${agentSelector}<p class="plan-help">${esc(T("inputHelp"))} <b>${esc(steps)} ${esc(T("steps").toLowerCase())}</b></p><textarea id="plan-editor" class="plan-editor" spellcheck="false">${esc(state.planText)}</textarea><div id="editor-errors" class="validation-list"></div>${proposal?.fallback?`<div class="notice warning">⚠ <span>${esc(T("fallback"))}<br><small>${esc(proposal.planner_error||"")}</small></span></div>`:""}`}
function activeProposal(){return state.session&&!terminal.has(state.session.state)?state.session.proposal||null:null}
function plannerActionMarkup(proposal,status){const mode=state.plannerMode;const session=state.session;const waiting=session&&["starting","planning","waiting_for_day","submitting","submitted"].includes(session.state);let buttons="";if(!proposal){buttons=`<button id="generate-plan" class="primary-button" ${waiting?"disabled":""}>${esc(mode==="auto"?T("startAuto"):T("generate"))}</button>`}else if(mode==="manual"||session?.execution_mode==="manual"||proposal.fallback){buttons=`<button id="submit-proposal" class="primary-button">${esc(proposal.kind==="agent_types"?T("submitTypes"):T("submitPlan"))}</button><button id="replan" class="secondary-button">${esc(T("replan"))}</button>`}else if(mode==="curl"||session?.execution_mode==="curl"){buttons=`<button id="reveal-curl" class="warning-button">${esc(T("revealCurl"))}</button><button id="replan" class="secondary-button">${esc(T("replan"))}</button>`}if(session&&!terminal.has(session.state)){buttons+=`<button id="cancel-session" class="text-button">${esc(T("cancel"))}</button>`}return`<div class="planner-actions">${buttons}<span class="safety-note">${esc(waiting?T("waiting"):T("lastValid"))}</span></div>${state.curlCommand?`<div class="notice warning">⚠ <span>${esc(T("tokenWarning"))}</span></div><pre class="curl-box">${esc(state.curlCommand)}<button id="copy-curl" class="secondary-button">${esc(T("copyCurl"))}</button></pre>`:""}`}
function plannerPanel(status){const canPlan=status==="selecting_agents"||status==="in_progress"||(status==="finished"&&state.game.is_practice&&!state.game.no_reset);if(!canPlan)return"";const s=state.session,active=Boolean(s&&!terminal.has(s.state));return`<section class="planner-panel"><div class="planner-head"><div><span class="eyebrow">HEXUDON</span><h2>${esc(T("planner"))}</h2></div></div><div class="planner-body"><div class="planner-grid"><div class="field"><label>${esc(T("method"))}</label><select id="method-select" ${active?"disabled":""}>${state.bootstrap.policies.map(m=>`<option value="${esc(m)}" ${m===state.method?"selected":""}>${esc(m)}</option>`).join("")}</select></div><div class="field"><label>${esc(T("timeLimit"))}</label><input id="time-limit" class="input" type="number" min="0.1" max="600" step="0.5" value="${esc(state.timeLimit)}" placeholder="daySeconds" ${active?"disabled":""}></div></div><p class="plan-help">${esc(T("timeLimitHelp"))}</p><div class="planner-actions">${active?`<button id="stop-search" class="warning-button">${esc(T("stopSearch"))}</button>`:`<button id="start-search" class="primary-button">${esc(T("startSearch"))}</button>`}<span class="safety-note">${esc(T("lastValid"))}</span></div><div class="notice">ⓘ <span>${esc(T("autoSubmitInfo"))}</span></div>${sessionMarkup()}</div></section>`}
function sessionMarkup(){const s=state.session;if(!s)return"";const p=s.progress||{},label=String(p.status||s.state||"").replaceAll("_"," "),best=p.best_score,bestText=Array.isArray(best)?`${best[0]}/${best[1]}/${best[2]}`:"—",subs=p.submission_count??0,dayNumber=Number(p.day??s.last_submission?.day);return`<div class="session-strip"><span class="session-state ${s.state==="failed"?"error":""}">${esc(label)}</span>${Number.isFinite(dayNumber)?`<span class="chip">${esc(T("day"))} ${dayNumber+1}</span>`:""}<span class="chip">${esc(T("best"))}: ${esc(bestText)}</span><span class="chip">${esc(T("submissionCount"))}: ${subs}</span>${s.error?`<span class="validation-error">${esc(s.error)}</span>`:""}</div>`}
function elapsedLabel(value){const seconds=Math.max(0,Number(value)||0);return seconds<10?`${seconds.toFixed(2)}s`:seconds<60?`${seconds.toFixed(1)}s`:`${Math.floor(seconds/60)}m ${(seconds%60).toFixed(1)}s`}
function incumbentScore(score){return Array.isArray(score)?score.slice(0,3).map(value=>Number(value)||0):[0,0,0]}
function rankArray(value,length){return Array.isArray(value)?Array.from({length},(_,index)=>Number(value[index])||0):new Array(length).fill(0)}
function internalImprovement(row,previous){if(!previous)return null;if(JSON.stringify(incumbentScore(row.score))!==JSON.stringify(incumbentScore(previous.score)))return"officialRank";const current=row.internal_rank,prior=previous.internal_rank;if(!current||!prior)return null;if(JSON.stringify(current.congestion)!==JSON.stringify(prior.congestion))return"trafficRank";if(JSON.stringify(current.workload)!==JSON.stringify(prior.workload))return"workloadRank";if(Number(current.patrol_fuel)!==Number(prior.patrol_fuel))return"patrolFuel";return null}
function internalRankMarkup(row,previous){const rank=row.internal_rank;if(!rank)return"";const congestion=rankArray(rank.congestion,6),workload=rankArray(rank.workload,3),reason=internalImprovement(row,previous),modeKey=`${["current","rolling","disabled"].includes(rank.congestion_mode)?rank.congestion_mode:"disabled"}Traffic`;return`<div class="internal-rank"><div class="internal-rank-head"><b>${esc(T("internalRank"))}</b><small>${esc(T("higherIsBetter"))}</small>${reason?`<span class="rank-reason">↑ ${esc(T("improvedBy"))}: ${esc(T(reason))}</span>`:""}</div><div class="rank-values"><span><i>${esc(T("trafficRank"))} (${esc(T(modeKey))})</i><code>[${congestion.join(", ")}]</code></span><span><i>${esc(T("workloadRank"))}</i><code>[${workload.join(", ")}]</code></span><span><i>${esc(T("patrolFuel"))}</i><code>${Number(rank.patrol_fuel)||0}</code></span></div></div>`}
function convergenceMarkup(){const s=state.session,all=Array.isArray(s?.incumbents)?s.incumbents:[];if(!all.length)return"";const progress=s.progress||{};let dayNumber=Number(progress.day??s.last_streamed_day??all.at(-1)?.day);let rows=all.filter(row=>Number(row.day)===dayNumber);if(!rows.length){dayNumber=Math.max(...all.map(row=>Number(row.day)||0));rows=all.filter(row=>Number(row.day)===dayNumber)}rows=rows.slice().sort((a,b)=>Number(a.day_sequence||a.sequence)-Number(b.day_sequence||b.sequence));const width=900,left=122,right=20,top=12,panelHeight=48,gap=13,plotWidth=width-left-right,height=top+3*panelHeight+2*gap+30,maxElapsed=Math.max(0.001,...rows.map(row=>Number(row.elapsed_seconds)||0),Number(progress.budget_seconds)||0),metrics=[[T("types"),0,"#5546eb"],[T("daily"),1,"#13b8aa"],[T("servings"),2,"#ff9f0a"]],x=value=>left+(Math.max(0,Number(value)||0)/maxElapsed)*plotWidth;const panels=metrics.map(([label,index,color],metricIndex)=>{const yTop=top+metricIndex*(panelHeight+gap),values=rows.map(row=>incumbentScore(row.score)[index]),maximum=Math.max(1,...values),y=value=>yTop+panelHeight-(value/maximum)*(panelHeight-8)-4;let path=`M ${x(rows[0].elapsed_seconds).toFixed(2)} ${y(values[0]).toFixed(2)}`;for(let i=1;i<rows.length;i++)path+=` H ${x(rows[i].elapsed_seconds).toFixed(2)} V ${y(values[i]).toFixed(2)}`;const points=rows.map((row,i)=>`<circle cx="${x(row.elapsed_seconds).toFixed(2)}" cy="${y(values[i]).toFixed(2)}" r="4" fill="${color}" stroke="#fff" stroke-width="2"><title>#${row.day_sequence||i+1} · ${elapsedLabel(row.elapsed_seconds)} · ${incumbentScore(row.score).join("/")}</title></circle>`).join("");return`<g><text x="0" y="${yTop+15}" class="chart-label">${esc(label)}</text><text x="${left-10}" y="${yTop+15}" text-anchor="end" class="chart-value">${values.at(-1)}</text><line x1="${left}" y1="${yTop+panelHeight}" x2="${width-right}" y2="${yTop+panelHeight}" class="chart-grid"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3" stroke-linejoin="round"/>${points}</g>`}).join("");const timeline=rows.map((row,index)=>({...row,previous:rows[index-1]||null,wait_seconds:(Number(row.elapsed_seconds)||0)-(index?Number(rows[index-1].elapsed_seconds)||0:0)})).slice(-8).reverse().map(row=>{const score=incumbentScore(row.score),submissionStatus=row.submission_status||(row.submitted?"submitted":"notSubmitted"),statusKey=submissionStatus==="pending"?"notSubmitted":submissionStatus,statusClass=submissionStatus==="submitted"?"done":submissionStatus,icon=submissionStatus==="submitted"?"✓ ":submissionStatus==="superseded"?"↗ ":"○ ";return`<li><span class="incumbent-index">#${row.day_sequence||row.sequence}</span><span><b>${esc(T("foundAt"))} ${elapsedLabel(row.elapsed_seconds)}</b><small>+${elapsedLabel(row.wait_seconds)} ${esc(T("sincePrevious"))}</small></span><strong>${score.join(" / ")}</strong><span class="submission-state ${statusClass}">${icon}${esc(T(statusKey))}</span>${internalRankMarkup(row,row.previous)}</li>`}).join("");return`<section class="convergence-panel"><div class="convergence-head"><div><span class="eyebrow">${esc(T("day"))} ${dayNumber+1}</span><h3>${esc(T("convergence"))}</h3></div><span class="chip primary">${rows.length} ${esc(T("incumbent"))}</span></div><p class="plan-help">${esc(T("convergenceHelp"))}</p><div class="convergence-chart"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(T("convergence"))}">${panels}<text x="${left}" y="${height-4}" class="chart-axis">0s</text><text x="${width-right}" y="${height-4}" text-anchor="end" class="chart-axis">${elapsedLabel(maxElapsed)}</text></svg></div><ol class="incumbent-timeline">${timeline}</ol></section>`}
function dayTabs(status){if(!state.game.is_practice||state.game.no_reset||!["in_progress","finished"].includes(status))return"";const total=state.game.total_days||1,current=Math.min(Number(state.snapshot.state?.day)||0,total-1);return`<div class="row"><span class="plan-help">${esc(T("editDay"))}:</span><div class="day-tabs">${Array.from({length:total},(_,i)=>`<button data-day="${i}" class="${state.selectedDay===i?"active":""}" ${status!=="finished"&&i>current?"disabled":""}>${esc(T("day"))} ${i+1}</button>`).join("")}</div></div>${state.selectedDay<current||status==="finished"?`<div class="notice warning">⚠ <span>${esc(T("resubmitWarn"))}</span></div>`:""}`}
function renderGame(){const snap=state.snapshot,game=state.game,config=snap.config||{},server=snap.state||{},status=server.status||"unknown",score=scoreSummary(),day=Number(server.day),total=game.total_days||config.daySteps?.length||0;const replayAvailable=status==="finished"||day>=1;const resettable=game.is_practice&&!game.no_reset;const statusNotice=status==="reset_incomplete"?`<div class="notice error">⚠ <span>${esc(server.error||T("reset_incomplete"))}</span></div>`:status==="finished"&&resettable?`<div class="notice success">✓ <span>${esc(T("finishedInfo"))}</span></div>`:"";$("#app").innerHTML=`<section class="game-heading"><div class="game-identity"><a href="/" class="icon-button back-button" title="${esc(T("back"))}">←</a><h1>HEXUDON</h1><span class="game-id">${esc(game.question_id)}</span><button id="copy-id" class="copy-button">▣</button></div></section><div class="status-chips"><span class="chip ${game.no_reset?"warning":"primary"}">${esc(gameModeLabel())}</span><span class="chip ${status==="finished"?"success":["in_progress","selecting_agents"].includes(status)?"selected":""}">${esc(statusLabel(status))}</span>${status!=="selecting_agents"?`<span class="chip">${esc(T("day"))} ${Math.min(day+1,total)}/${total}</span>`:""}<span class="chip">${esc(T("types"))}: ${score.types}</span><span class="chip">${esc(T("servings"))}: ${score.servings}</span><div class="toolbar"><button id="config-button" class="secondary-button">☷ ${esc(T("config"))}</button>${replayAvailable?`<button id="replay-button" class="secondary-button">↻ ${esc(T("replay"))}</button>`:""}${!game.is_practice&&replayAvailable?`<button id="answers-button" class="secondary-button">▤ ${esc(T("answers"))}</button>`:""}${resettable?`<button id="reset-button" class="warning-button">↻ ${esc(T("reset"))}</button>`:""}</div></div><section class="panel">${statusNotice}${dayTabs(status)}${plannerPanel(status)}${convergenceMarkup()}</section><section class="panel map-panel"><div class="map-toolbar"><button class="icon-button map-icon-button" data-zoom="out" aria-label="Zoom out" ${state.zoom<=.5?"disabled":""}>${zoomIcon("out")}</button><button class="zoom-label text-button" data-zoom="reset">${Math.round(state.zoom*100)}%</button><button class="icon-button map-icon-button" data-zoom="in" aria-label="Zoom in" ${state.zoom>=3?"disabled":""}>${zoomIcon("in")}</button></div><div class="map-wrap"><div class="map-canvas">${renderMap()}</div></div>${legendMarkup()}</section>${standingsMarkup()}`;bindGame()}

function geometry(config,radius){const width=config.map?.width||1,height=config.map?.height||1,w=Math.sqrt(3)*radius;return{width,height,w,viewWidth:(width+1.5)*w,viewHeight:(height+1)*1.5*radius+radius,center(pos){const row=Math.floor(pos/width),col=pos%width;return{x:col*w+(row%2===0?w/2:0)+w,y:row*1.5*radius+2*radius}},corners(pos){const c=this.center(pos);return Array.from({length:6},(_,i)=>{const a=(Math.PI/180)*(60*i-30);return`${c.x+radius*Math.cos(a)},${c.y+radius*Math.sin(a)}`}).join(" ")}}}
function renderMap({config=state.session?.snapshot?.config||state.snapshot.config,day=state.session?.snapshot?.day||state.snapshot.day,replayTeams=null,finalTeams=null,highlightCells=[]}={}){if(!config?.map)return`<div class="empty">${esc(T("map"))}</div>`;const radius=16*state.zoom,g=geometry(config,radius),cells=config.map.cells.flat(),roads=Object.fromEntries((day?.traffics||[]).map(x=>[Number(x.pos),Number(x.status)])),terrainColors={0:"#b5d99c",2:"#a1887f",3:"#64b5f6"},roadColors=["#d6d6d6","#f3c969","#e57373"],teamColors=["#8e24aa","#ef6c00","#00838f","#c2185b","#5d4037"];let content=cells.map((terrain,pos)=>{const fill=terrain===1?roadColors[roads[pos]??0]:terrainColors[terrain];return`<polygon points="${g.corners(pos)}" fill="${fill}" stroke="#607d5b" stroke-width=".6"><title>#${pos}</title></polygon>`}).join("");content+=(config.spots||[]).map(spot=>{const p=g.center(Number(spot.pos));return`<g><circle cx="${p.x}" cy="${p.y}" r="${radius*.52}" fill="#fff59d" stroke="#f9a825" stroke-width="1.2"/><text x="${p.x}" y="${p.y+radius*.2}" text-anchor="middle" font-size="${radius*.62}" fill="#795548" font-weight="bold">${esc(spot.brand)}</text><title>Spot: brand ${esc(spot.brand)}, stock ${esc(spot.stocks)}/day</title></g>`}).join("");content+=(highlightCells||[]).map(cell=>{const p=g.center(Number(cell));return`<circle cx="${p.x}" cy="${p.y}" r="${radius*.95}" fill="none" stroke="#d32f2f" stroke-width="2.4" opacity=".9"/>`}).join("");if(replayTeams){for(const team of replayTeams)for(const [index,agent] of (team.agents||[]).entries()){if((agent.trail||[]).length<2)continue;const points=agent.trail.map(cell=>{const p=g.center(cell);return`${p.x},${p.y}`}).join(" ");content+=`<polyline points="${points}" fill="none" stroke="${team.color}" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" stroke-dasharray="1 4" opacity=".55"/>`}const byCell={};replayTeams.forEach((team,ti)=>(team.agents||[]).forEach((agent,ai)=>(byCell[agent.cell]||=[]).push({team,ti,agent,ai})));for(const [cell,items] of Object.entries(byCell)){const center=g.center(Number(cell)),count=items.length,markerRadius=radius*(count>4?.3:.38),orbit=count===1?0:radius*.44;items.forEach((item,index)=>{const angle=2*Math.PI*index/count-Math.PI/2,x=center.x+Math.cos(angle)*orbit,y=center.y+Math.sin(angle)*orbit,refuel=Number(item.agent.kind)===1;content+=`<g><circle cx="${x}" cy="${y}" r="${markerRadius}" fill="${refuel?"#fff":item.team.color}" stroke="${item.team.color}" stroke-width="2.4"/><text x="${x}" y="${y+markerRadius*.55}" text-anchor="middle" font-size="${markerRadius*1.2}" font-weight="bold" fill="${refuel?item.team.color:"#fff"}">${item.ai}</text><title>${esc(item.team.label||item.team.teamId)} · ${refuel?"refuel":"patrol"} #${item.ai}</title></g>`})}for(const team of finalTeams||[])(team.agents||[]).forEach((agent,index)=>{const p=g.center(Number(agent.cell)),size=radius*.36,offset=((team.index||0)%3-1)*radius*.22,x=p.x+offset;content+=`<g><rect x="${x-size}" y="${p.y-size}" width="${size*2}" height="${size*2}" transform="rotate(45 ${x} ${p.y})" fill="#fff" fill-opacity=".75" stroke="${team.color}" stroke-width="2" stroke-dasharray="3 2"/><text x="${x}" y="${p.y+size*.5}" text-anchor="middle" font-size="${size*1.05}" font-weight="bold" fill="${team.color}">${index}</text></g>`})}else{const proposal=activeProposal(),frames=proposal?.trace?.frames||[];if(frames.length){const count=frames[0]?.agents?.length||0;for(let ai=0;ai<count;ai++){const cells=[];for(const frame of frames){const cell=frame.agents?.[ai]?.cell;if(cell!=null&&cells.at(-1)!==cell)cells.push(cell)}if(cells.length<2)continue;const points=cells.map(cell=>{const p=g.center(cell);return`${p.x},${p.y}`}).join(" "),selected=ai===state.selectedAgent;content+=`<polyline points="${points}" fill="none" stroke="${selected?"#d32f2f":"#7b1fa2"}" stroke-width="${selected?2.4:1.4}" stroke-dasharray="${selected?"":"4 3"}" opacity="${selected?.95:.6}"/>`}}for(const [otherIndex,other] of (day?.others||[]).entries())for(const [agentIndex,agent] of (other.agents||[]).entries())content+=normalMarker(g,radius,agent.pos,teamColors[otherIndex%teamColors.length],agentIndex,false,1);for(const [index,agent] of (day?.agents||[]).entries())content+=normalMarker(g,radius,agent.pos,Number(agent.kind)===0?"#1976d2":"#2e7d32",index,true,0)}return`<svg class="hex-map" width="${g.viewWidth}" height="${g.viewHeight}" role="img" aria-label="HEXUDON map">${content}</svg>`}
function normalMarker(g,radius,cell,color,label,big=false,offset=0){const p=g.center(Number(cell)),markerRadius=radius*(big?.46:.32),dx=offset*radius*.35;return`<g><circle cx="${p.x+dx}" cy="${p.y-radius*.35}" r="${markerRadius}" fill="${color}" stroke="#fff" stroke-width="1.2"/><text x="${p.x+dx}" y="${p.y-radius*.35+markerRadius*.55}" text-anchor="middle" font-size="${markerRadius*1.15}" fill="#fff" font-weight="bold">${label}</text></g>`}
function legendMarkup(replay=false){const swatches=[["plain",T("plain")],["mountain",T("mountain")],["pond",T("pond")],["road-clear",T("road0")],["road-busy",T("road1")],["road-jammed",T("road2")]];return`<div class="legend">${swatches.map(([kind,label])=>`<span><i class="swatch-${kind}"></i>${esc(label)}</span>`).join("")}<span><i class="round swatch-spot"></i>${esc(T("spot"))}</span>${replay?`<span>● ${esc(T("patrol"))} · ○ ${esc(T("refuel"))}</span>`:`<span><i class="round swatch-patrol"></i>${esc(T("patrol"))}</span><span><i class="round swatch-refuel"></i>${esc(T("refuel"))}</span>`}</div>`}
function standingsMarkup(){const peer=state.peerStandings;if(state.game?.is_practice&&peer){if(peer.loading)return`<section class="panel standings standings-loading"><h3>${esc(T("standings"))}</h3><span class="spinner"></span></section>`;if(peer.ranking?.length){const names=Object.fromEntries((peer.teams||state.game.teams||[]).map(team=>[String(team.id),team.name]));return`<section class="panel standings"><h3>${esc(T("standings"))}</h3><div class="standings-scroll"><table><thead><tr><th>#</th><th>${esc(T("team"))}</th><th class="numeric">${esc(T("types"))}</th><th class="numeric">${esc(T("daily"))}</th><th class="numeric">${esc(T("servings"))}</th><th class="numeric">${esc(T("response"))}</th></tr></thead><tbody>${peer.ranking.map((id,index)=>{const row=peer.detail?.[id]||{},own=String(id)===String(peer.own_team_id||ownTeamId());return`<tr class="${own?"you":""}"><td>${index+1}</td><td><b>${esc(names[id]||id)}</b><small class="team-id">#${esc(id)}${own?" · you":""}</small></td><td class="numeric">${row.distinct_types??0}</td><td class="numeric">${row.cumulative_daily_types??0}</td><td class="numeric">${row.total_servings??0}</td><td class="numeric">${Number(row.cumulative_response_time??0).toFixed(3)}s</td></tr>`}).join("")}</tbody></table></div></section>`}}const competitive=state.snapshot.competitive_state?.standings;if(competitive){const ranking=competitive.ranking||[];return`<section class="panel standings"><h3>${esc(T("standings"))}</h3><table><thead><tr><th>#</th><th>${esc(T("team"))}</th><th>${esc(T("days"))}</th></tr></thead><tbody>${ranking.map((team,i)=>`<tr class="${String(team)===ownTeamId()?"you":""}"><td>${i+1}</td><td>${esc(team)}${String(team)===ownTeamId()?" (you)":""}</td><td>${esc(competitive.owned_days?.[team]??0)}</td></tr>`).join("")}</tbody></table></section>`}const teams=state.snapshot.state?.teams;if(!teams)return peer?.error?`<section class="panel notice error">${esc(peer.error)}</section>`:"";return`<section class="panel standings"><h3>${esc(T("standings"))}</h3><table><thead><tr><th>${esc(T("team"))}</th><th>${esc(T("types"))}</th><th>${esc(T("servings"))}</th><th>${esc(T("submissionCount"))}</th></tr></thead><tbody>${Object.entries(teams).map(([id,row])=>`<tr class="${id===ownTeamId()?"you":""}"><td>${esc(id)}${id===ownTeamId()?" (you)":""}</td><td>${(row.distinct_types||[]).length}</td><td>${row.total_servings??0}</td><td>${row.submit_count??0}</td></tr>`).join("")}</tbody></table></section>`}

function bindGame(){
 $("#copy-id")?.addEventListener("click",()=>copy(state.game.question_id));$("#refresh-button")?.addEventListener("click",()=>loadGame(state.game.question_id,{quiet:true}));$("#config-button")?.addEventListener("click",showConfig);$("#replay-button")?.addEventListener("click",showReplay);$("#answers-button")?.addEventListener("click",showAnswers);$("#reset-button")?.addEventListener("click",resetGame);
 $("#method-select")?.addEventListener("change",e=>{state.method=e.target.value});$("#time-limit")?.addEventListener("input",e=>{state.timeLimit=e.target.value});
 $$("[data-role-index]").forEach(b=>b.addEventListener("click",()=>{state.roles[Number(b.dataset.roleIndex)]=Number(b.dataset.role);renderGame()}));$("#plan-editor")?.addEventListener("input",e=>{state.planText=e.target.value;validateEditor()});validateEditor();
 $$('[data-agent-select]').forEach(b=>b.addEventListener("click",()=>{state.selectedAgent=Number(b.dataset.agentSelect);renderGame()}));
 $("#start-search")?.addEventListener("click",startPlanning);$("#stop-search")?.addEventListener("click",()=>controlSession("cancel"));
 $$("[data-day]").forEach(b=>b.addEventListener("click",()=>switchDay(Number(b.dataset.day))));$$('[data-zoom]').forEach(b=>b.addEventListener("click",()=>{state.zoom=b.dataset.zoom==="in"?Math.min(3,state.zoom*1.25):b.dataset.zoom==="out"?Math.max(.5,state.zoom/1.25):1;renderGame()}));
}
function validateEditor(){const node=$("#editor-errors"),proposal=activeProposal();if(!node||proposal?.kind!=="day_plan")return;try{const value=JSON.parse(state.planText);if(!Array.isArray(value))throw new Error("plan must be an array");node.innerHTML="";$("#submit-proposal")&&( $("#submit-proposal").disabled=false)}catch(error){node.innerHTML=`<span class="validation-error">${esc(error.message)}</span>`;$("#submit-proposal")&&( $("#submit-proposal").disabled=true)}}
function collectParams(){const result={};$$('[data-param]').forEach(input=>{if(input.value!=="")result[input.dataset.param]=Number(input.value)});return result}
async function startPlanning(){try{if(state.session&&!terminal.has(state.session.state))await controlSession("cancel",false);state.curlCommand="";const body={game_id:state.game.question_id,method:state.method,execution_mode:"auto"};const limit=parseFloat(state.timeLimit);if(state.timeLimit!==""&&Number.isFinite(limit))body.time_limit_seconds=limit;state.session=await post("/api/play/sessions",body);syncProposal();renderGame();scheduleSessionPoll()}catch(error){toast(error.message,"error")}}
function syncProposal(){if(state.session?.snapshot)state.snapshot={...state.snapshot,...state.session.snapshot};const proposal=activeProposal();if(!proposal||proposal.fingerprint===state.proposalFingerprint)return;state.proposalFingerprint=proposal.fingerprint;state.curlCommand="";if(proposal.kind==="day_plan"){state.selectedDay=Number(proposal.day);state.planText=JSON.stringify(proposal.actions)}else state.roles=proposal.types.slice()}
async function switchDay(day){const session=state.session,proposalDay=session?.proposal?.kind==="day_plan"?Number(session.proposal.day):null,progressDay=Number(session?.progress?.day);if(session&&!terminal.has(session.state)){const expected=proposalDay??(Number.isFinite(progressDay)?progressDay:null);if(expected===day){state.selectedDay=day;syncProposal();renderGame();scheduleSessionPoll();return}if(!confirm(T("switchDayConfirm")))return;await controlSession("cancel",false)}state.selectedDay=day;state.session=null;state.planText="";state.proposalFingerprint=null;state.curlCommand="";renderGame()}
function scheduleSessionPoll(){clearTimeout(state.sessionTimer);if(!state.session||terminal.has(state.session.state))return;state.sessionTimer=setTimeout(pollSession,800)}
async function pollSession(){if(!state.session)return;try{const next=await api(`/api/play/sessions/${state.session.id}`);const changed=next.state!==state.session.state||next.progress?.submission_count!==state.session.progress?.submission_count||(next.incumbents?.length||0)!==(state.session.incumbents?.length||0)||next.last_submission?.submitted_at!==state.session.last_submission?.submitted_at||next.error!==state.session.error;state.session=next;syncProposal();if(changed)renderGame();if(next.state==="finished"){await loadGame(state.game.question_id,{quiet:true});return}scheduleSessionPoll()}catch(error){toast(error.message,"error")}}
async function submitProposal(){const p=activeProposal();if(!p)return;try{const payload={fingerprint:p.fingerprint,allow_fallback:Boolean(p.fallback)};if(p.kind==="agent_types")payload.types=state.roles;else payload.actions=JSON.parse(state.planText);state.session=await post(`/api/play/sessions/${state.session.id}/submit`,payload);renderGame();scheduleSessionPoll()}catch(error){toast(error.message,"error")}}
async function revealCurl(){const p=activeProposal();if(!p||!confirm(`${T("curlWarning")}\n\n${T("tokenWarning")}`))return;try{const payload={fingerprint:p.fingerprint};if(p.kind==="agent_types")payload.types=state.roles;else payload.actions=JSON.parse(state.planText);const result=await post(`/api/play/sessions/${state.session.id}/curl`,payload);state.curlCommand=result.command;renderGame()}catch(error){toast(error.message,"error")}}
async function controlSession(action,rerender=true){if(!state.session)return;try{state.session=await post(`/api/play/sessions/${state.session.id}/control`,{action});if(action==="cancel"){state.session=null;state.proposalFingerprint=null;state.planText=""}if(rerender)renderGame();else return state.session;scheduleSessionPoll()}catch(error){toast(error.message,"error")}}
async function resetGame(){if(!confirm(T("resetConfirm")))return;try{clearTimeout(state.sessionTimer);if(state.session&&!terminal.has(state.session.state))await post(`/api/play/sessions/${state.session.id}/control`,{action:"cancel"});await post(`/api/games/${encodeURIComponent(state.game.question_id)}/reset`,{});state.session=null;state.selectedDay=0;state.selectedAgent=0;state.planText="";state.roles=[];state.proposalFingerprint=null;state.curlCommand="";toast(T("refresh"),"success");await loadGame(state.game.question_id,{quiet:true})}catch(error){toast(error.message,"error")}}

function openModal(title,body,{wide=false}={}){$("#modal-root").innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?"wide":""}"><header class="modal-head"><h2>${esc(title)}</h2><button class="close-button" aria-label="${esc(T("close"))}">×</button></header><div class="modal-body">${body}</div></section></div>`;$(".close-button").addEventListener("click",closeModal);$(".modal-backdrop").addEventListener("click",e=>{if(e.target.classList.contains("modal-backdrop"))closeModal()})}
function closeModal(){clearInterval(state.replayTimer);if(state.replayFrameRequest)cancelAnimationFrame(state.replayFrameRequest);$("#modal-root").innerHTML=""}
function showConfig(){const c=state.snapshot.config;const fmt=v=>v?new Date(Number(v)*1000).toLocaleString():"—";openModal(T("gameConfig"),`<div class="config-grid">${[[T("mapSize"),`${c.map.width} × ${c.map.height}`],[T("players"),c.players],[T("days"),c.daySteps.length],[T("fuel"),c.fuelLimits],[T("spots"),c.spots.length],[T("congestion"),`${c.busyThreshold} / ${c.jammedThreshold}`],[T("selectTime"),`${c.agent_selection_time_limit??60}s`],[T("startsAt"),fmt(c.startsAt)]].map(([l,v])=>`<div class="config-item"><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join("")}</div><h3>${esc(T("perDay"))}</h3><table><thead><tr><th>${esc(T("day"))}</th><th>${esc(T("steps"))}</th><th>${esc(T("seconds"))}</th></tr></thead><tbody>${c.daySteps.map((steps,i)=>`<tr><td>${i+1}</td><td>${steps}</td><td>${c.daySeconds[i]}</td></tr>`).join("")}</tbody></table><div class="row raw-head"><h3>${esc(T("raw"))}</h3><button id="copy-config" class="secondary-button">${esc(T("copyData"))}</button></div><pre class="raw-json">${esc(JSON.stringify(c,null,2))}</pre>`);$("#copy-config").addEventListener("click",()=>copy(JSON.stringify(c)))}
async function showAnswers(){openModal(T("answersTitle"),`<div class="loading-screen"><div class="spinner"></div></div>`);try{const data=await api(`/api/games/${encodeURIComponent(state.game.question_id)}/answers`),rows=data.actions||[],body=$(".modal-body");if(!body)return;body.innerHTML=rows.length?`<table><thead><tr><th>${esc(T("day"))}</th><th>${esc(T("team"))}</th><th>${esc(T("plan"))}</th><th>${esc(T("submissionCount"))}</th><th>${esc(T("submittedAt"))}</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${Number(row.day)+1}</td><td>${esc(row.team_id)}</td><td><pre class="raw-json">${esc(JSON.stringify(row.plan))}</pre></td><td>${row.submit_count??1}</td><td>${row.submitted_at?new Date(row.submitted_at*1000).toLocaleTimeString():"—"}</td></tr>`).join("")}</tbody></table>`:`<p>${esc(T("noAnswers"))}</p>`}catch(error){const body=$(".modal-body");if(body)body.innerHTML=`<div class="notice error">${esc(error.message)}</div>`}}
async function showReplay(){
 openModal(T("replayTitle"),`<div class="loading-screen"><div class="spinner"></div></div>`,{wide:true});
 try{
  const gameId=encodeURIComponent(state.game.question_id),own=await api(`/api/games/${gameId}/replay`),replays=[own.replay];
  if(state.game.is_practice){
   const peerIds=(state.game.team_ids||[]).map(String).filter(id=>id!==ownTeamId());
   const peers=await Promise.all(peerIds.map(id=>api(`/api/games/${gameId}/replay?team_id=${encodeURIComponent(id)}`).catch(()=>null)));
   replays.push(...peers.filter(Boolean).map(row=>row.replay));
  }
  if(!$(".modal-body"))return;
  const merged=new Map();
  for(const replay of replays)for(const day of replay?.days||[]){
   const key=Number(day.day),target=merged.get(key)||{...day,teams:[]},known=new Set(target.teams.map(team=>String(team.team_id)));
   for(const team of day.teams||[])if(!known.has(String(team.team_id))){target.teams.push(team);known.add(String(team.team_id))}
   merged.set(key,target);
  }
  const data={days:[...merged.values()].sort((a,b)=>Number(a.day)-Number(b.day))},teams=new Set();
  for(const day of data.days)for(const team of day.teams||[])teams.add(String(team.team_id));
  state.replay={data,dayIndex:0,step:0,playing:false,showFinal:true,visible:new Set(teams)};
  renderReplay();
 }catch(error){const body=$(".modal-body");if(body)body.innerHTML=`<div class="notice error">${esc(error.message)}</div>`}
}
function replayTrail(frames,agentIndex,step){
 const cells=[];
 for(const frame of frames.slice(0,Math.min(step,frames.length-1)+1)){
  const cell=frame.agents?.[agentIndex]?.cell;
  if(cell!=null&&cells.at(-1)!==Number(cell))cells.push(Number(cell));
 }
 return cells;
}
function replayFrameData(){
 const r=state.replay,day=r.data.days[r.dayIndex],allTeams=day.teams||[],max=Math.max(Number(day.steps)||0,...allTeams.map(team=>(team.frames?.length||1)-1)),colors=["#1976d2","#8e24aa","#ef6c00","#00838f","#c2185b","#5d4037"];
 r.step=Math.min(r.step,max);
 const colorIndexFor=id=>Math.max(0,allTeams.findIndex(team=>String(team.team_id)===String(id)))%colors.length,colorFor=id=>colors[colorIndexFor(id)];
 const replayTeams=allTeams.filter(team=>r.visible.has(String(team.team_id))).map(team=>{const frameIndex=Math.min(r.step,(team.frames?.length||1)-1),frame=team.frames?.[frameIndex]||team.frames?.[0];return{teamId:team.team_id,label:`${T("team")} ${team.team_id}`,color:colorFor(team.team_id),agents:(frame?.agents||[]).map((agent,index)=>({cell:Number(agent.cell),kind:agent.type==="refuel"||Number(agent.type)===1?1:0,fuel:agent.fuel,trail:replayTrail(team.frames||[],index,frameIndex)}))}});
 const finalTeams=r.showFinal?allTeams.filter(team=>!r.visible.has(String(team.team_id))).map((team,index)=>{const frame=team.frames?.at(-1);return{teamId:team.team_id,index,color:colorFor(team.team_id),agents:(frame?.agents||[]).map(agent=>({cell:Number(agent.cell)}))}}):[];
 const rows=allTeams.filter(team=>r.visible.has(String(team.team_id))).map(team=>{const frame=team.frames?.[Math.min(r.step,(team.frames?.length||1)-1)]||team.frames?.[0]||{},agents=frame.agents||[],collectedNow=(frame.collected||[]).length;return`<tr><td><span class="team-dot team-color-${colorIndexFor(team.team_id)}"></span>${esc(T("team"))} ${esc(team.team_id)}</td><td class="numeric">${frame.servings??0}/${team.servings??frame.servings??0}</td><td class="numeric">${frame.types??0}/${team.types??frame.types??0}</td><td class="numeric">${collectedNow>0?`+${collectedNow}`:"—"}</td><td><div class="agent-fuel-list">${agents.map((agent,index)=>`<span class="agent-fuel-chip">#${index} ${esc(agent.type==="refuel"||Number(agent.type)===1?T("refuel"):`${T("patrol")} ⛽${agent.fuel??"—"}`)}</span>`).join("")}</div></td></tr>`}).join("");
 return{day,allTeams,max,colorIndexFor,replayTeams,finalTeams,rows,dayInfo:{traffics:Object.entries(day.road_condition||{}).map(([pos,status])=>({pos:Number(pos),status}))}};
}
function updateReplayFrame(){
 state.replayFrameRequest=null;
 if(!state.replay||!$("#replay-range"))return;
 const r=state.replay,view=replayFrameData(),range=$("#replay-range");
 range.max=String(view.max);range.value=String(r.step);
 $("#replay-step-label").textContent=`${T("steps")} ${r.step}/${view.max}`;
 $("#replay-play").textContent=r.playing?"Ⅱ":"▶";
 $("#replay-rows").innerHTML=view.rows;
 $("#replay-map-canvas").innerHTML=renderMap({config:state.snapshot.config,day:view.dayInfo,replayTeams:view.replayTeams,finalTeams:view.finalTeams});
 $$('[data-replay-team]').forEach(button=>button.classList.toggle("is-hidden",!r.visible.has(button.dataset.replayTeam)));
}
function queueReplayFrame(){if(state.replayFrameRequest)cancelAnimationFrame(state.replayFrameRequest);state.replayFrameRequest=requestAnimationFrame(updateReplayFrame)}
function stopReplay(){state.replay.playing=false;clearInterval(state.replayTimer)}
function renderReplay(){
 const r=state.replay,days=r.data?.days||[],body=$(".modal-body");
 if(!days.length){body.innerHTML=`<p>${esc(T("replayEmpty"))}</p>`;return}
 const view=replayFrameData(),finalLabel=state.locale==="vi"?"Hiện vị trí cuối của đội ẩn":"Show final positions of hidden teams";
 body.innerHTML=`<div class="day-tabs">${days.map((value,index)=>`<button data-replay-day="${index}" class="${index===r.dayIndex?"active":""}">${esc(T("day"))} ${Number(value.day)+1}</button>`).join("")}</div><div class="replay-controls"><button id="replay-first" class="icon-button" title="${esc(T("first"))}">|◀</button><button id="replay-play" class="icon-button" title="${esc(T("play"))}">${r.playing?"Ⅱ":"▶"}</button><button id="replay-last" class="icon-button" title="${esc(T("last"))}">▶|</button><input id="replay-range" type="range" min="0" max="${view.max}" value="${r.step}"><span id="replay-step-label"></span></div><div class="replay-options"><div class="replay-teams">${view.allTeams.map(team=>`<button class="replay-team team-border-${view.colorIndexFor(team.team_id)} ${r.visible.has(String(team.team_id))?"":"is-hidden"}" data-replay-team="${esc(team.team_id)}">${esc(T("team"))} ${esc(team.team_id)} · ${team.servings??0}</button>`).join("")}</div><label><input id="replay-final" type="checkbox" ${r.showFinal?"checked":""}> ${esc(finalLabel)}</label></div><div class="replay-table"><table><thead><tr><th>${esc(T("team"))}</th><th class="numeric">${esc(T("servings"))}</th><th class="numeric">${esc(T("types"))}</th><th class="numeric">${esc(T("collected"))}</th><th>${esc(T("agentsFuel"))}</th></tr></thead><tbody id="replay-rows"></tbody></table></div><div class="map-wrap replay-map"><div id="replay-map-canvas" class="map-canvas"></div></div>${legendMarkup(true)}`;
 $$('[data-replay-day]').forEach(button=>button.onclick=()=>{stopReplay();r.dayIndex=Number(button.dataset.replayDay);r.step=0;renderReplay()});
 $$('[data-replay-team]').forEach(button=>button.onclick=()=>{const id=button.dataset.replayTeam;r.visible.has(id)?r.visible.delete(id):r.visible.add(id);updateReplayFrame()});
 $("#replay-final").onchange=event=>{r.showFinal=event.target.checked;updateReplayFrame()};
 $("#replay-range").oninput=event=>{stopReplay();r.step=Number(event.target.value);queueReplayFrame()};
 $("#replay-first").onclick=()=>{stopReplay();r.step=0;updateReplayFrame()};
 $("#replay-last").onclick=()=>{stopReplay();r.step=view.max;updateReplayFrame()};
 $("#replay-play").onclick=()=>{if(r.step>=view.max)r.step=0;r.playing=!r.playing;clearInterval(state.replayTimer);if(r.playing)state.replayTimer=setInterval(()=>{const current=replayFrameData();if(r.step>=current.max){stopReplay()}else r.step++;updateReplayFrame()},700);updateReplayFrame()};
 updateReplayFrame();
}

$("#locale-button").addEventListener("click",()=>{state.locale=state.locale==="vi"?"en":"vi";localStorage.setItem("hex-locale",state.locale);renderLocale();currentGameId()?renderGame():isLocalRoute()?renderLocal():renderHome()});
boot();
